<?php
require_once dirname(__DIR__,2).'/src/media.php';require_method('POST');$u=current_user();$d=request_json();
$name=trim((string)($d['name']??''));$username=trim((string)($d['username']??''));$bio=trim((string)($d['bio']??''));
if($name===''||strlen($name)>100||!preg_match('/^[a-zA-Z0-9_.]{3,30}$/',$username)||$bio===''||strlen($bio)>500)json_response(['error'=>['code'=>'invalid_profile','message'=>'Provide a name, a 3–30 character username (letters, numbers, underscore or dot), and bio']],400);
try { mutate($u,$d,'profile.update',function($pdo)use($u,$name,$username,$bio,$d){foreach(['photo_media_id','cover_media_id'] as $field){if(array_key_exists($field,$d)&&$d[$field]!==null)owned_media($d[$field],$u['id'],'image/');}$q=$pdo->prepare('UPDATE users SET display_name=?,username=?,username_normalized=?,bio=?,profile_setup_complete=1,updated_at=UTC_TIMESTAMP(6) WHERE id=?');$q->execute([$name,$username,strtolower($username),$bio,$u['id']]);foreach(['website'=>200,'phone'=>30] as $field=>$max){if(array_key_exists($field,$d)){$value=trim((string)$d[$field]);if(strlen($value)>$max)throw new DomainException(ucfirst($field).' is too long');$q=$pdo->prepare("UPDATE users SET $field=? WHERE id=?");$q->execute([$value,$u['id']]);}}foreach(['photo_media_id','cover_media_id'] as $field){if(array_key_exists($field,$d)){$q=$pdo->prepare("UPDATE users SET $field=? WHERE id=?");$q->execute([$d[$field],$u['id']]);}}$q=$pdo->prepare('SELECT id,display_name,username,bio,photo_media_id,cover_media_id,profile_setup_complete,first_name,last_name,gender,website,email,phone,birthday FROM users WHERE id=?');$q->execute([$u['id']]);return ['user'=>$q->fetch()];}); }
catch(PDOException $e){if($e->getCode()==='23000')json_response(['error'=>['code'=>'username_taken','message'=>'Username already taken']],409);throw $e;}
